import {startModel} from './model.js';
const $=id=>document.getElementById(id);let workspace={lessons:[],drafts:[],attempts:[]},image='',answer='',busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5500);}
async function api(url,data){const response=await fetch('/api/'+url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
function go(view){document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==view);document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('view-title').textContent=document.querySelector(`[data-view="${view}"]`).textContent.replace(/\d+$/,'').trim();if(view==='practice')startModel();}
document.querySelectorAll('.nav').forEach(x=>x.onclick=()=>go(x.dataset.view));
async function refresh(){workspace=await api('workspace');$('connection').textContent=workspace.connected?'Gemini connected':'Local demo mode';$('model-name').value=workspace.model;$('queue-count').textContent=workspace.drafts.filter(x=>x.status!=='reviewed').length;renderLibrary();renderReview();$('practice-record').textContent=workspace.attempts.length?`${workspace.attempts.filter(x=>x.correct).length} correct out of ${workspace.attempts.length} attempts. This is a vocabulary check, not certification.`:'No attempts yet.';}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this file.'));reader.readAsDataURL(file);});}
$('photo').onchange=async()=>{const file=$('photo').files[0];if(!file)return;if(file.size>6*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Use a JPEG, PNG or WebP photo under 6 MB.');$('photo').value='';return;}image=await fileData(file);$('photo-preview').src=image;$('photo-preview').hidden=false;$('photo-placeholder').hidden=true;};
const traceHTML=trace=>`<div class="trace">${trace.map(x=>`<div class="trace-row"><span class="trace-icon">✓</span><div><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div></div>`).join('')}</div>`;
async function coach(){if(busy)return;busy=true;$('coach-submit').disabled=true;$('coach-submit').textContent='Finding your learning path…';$('result').innerHTML='<div class="panel-title"><span class="number">02</span><h2>Checking your sources</h2></div><p aria-live="polite">Confirming equipment and searching the approved library…</p>';try{const result=await api('coach',{tool:$('tool').value,question:$('question').value,image});$('result').innerHTML=`<div class="panel-title"><span class="number">02</span><h2>${result.type==='lesson'?'Your matching lesson':result.type==='draft'?'A lesson draft is ready':'Your trainer can help'}</h2></div><span class="tag">${esc(result.mode)}</span>${result.lesson?`<h3>${esc(result.lesson.title)}</h3><video controls preload="metadata" src="${esc(result.lesson.video)}#t=${result.lesson.start}"></video><p class="source-ref">Source: ${esc(result.lesson.title)} · ${esc(result.lesson.tool)} · Trainer approved</p>`:''}<p class="result-copy">${esc(result.answer)}</p><button class="primary" id="next-step">${result.type==='lesson'?'Practice in 3D':'View trainer queue'}</button>${traceHTML(result.trace)}`;$('next-step').onclick=()=>go(result.type==='lesson'?'practice':'review');await refresh();return result;}catch(e){$('result').innerHTML=`<h2>We couldn’t complete this request</h2><p class="error">${esc(e.message)}</p><p>Your library has not been changed. Update the request or connection and try again.</p>`;toast(e.message);}finally{busy=false;$('coach-submit').disabled=false;$('coach-submit').textContent='Find my lesson';}}
$('coach-form').onsubmit=e=>{e.preventDefault();coach();};
$('sample').onclick=()=>{go('coach');$('tool').value='Training pipe layout kit';$('question').value='Which fitting creates a branch in this pipe layout?';image='';$('photo-preview').hidden=true;$('photo-placeholder').hidden=false;$('photo').value='';$('result').innerHTML='<div class="panel-title"><span class="number">02</span><h2>Sample learning path</h2></div><span class="tag">SAMPLE · NOT COMPANY TRAINING</span><h3>Recognize a tee fitting</h3><p>A tee has three openings and can connect a branch to a main pipe run. An elbow changes direction; a straight section continues a run.</p><p class="source-ref">Prepared demo vocabulary only. No equipment identification or AI analysis has been performed.</p><button id="sample-practice" class="primary">Try the 3D exercise</button>';$('sample-practice').onclick=()=>go('practice');};
function renderLibrary(){$('library-list').innerHTML=workspace.lessons.length?workspace.lessons.map(x=>`<article class="panel lesson-card"><div><span class="tag">${x.approved?'TRAINER APPROVED':'AWAITING REVIEW'}</span><h2>${esc(x.title)}</h2><p>${esc(x.tool)} · ${esc(x.topic||'General')}</p><p class="small">${x.video?'Video + written reference':'Written reference only'} · Starts at ${x.start}s</p><details><summary>Read reference</summary><p class="result-copy">${esc(x.content)}</p></details>${x.video?`<video controls preload="none" src="${esc(x.video)}#t=${x.start}"></video>`:''}</div><div class="lesson-actions"><button class="secondary" data-approval="${x.id}" data-value="${!x.approved}">${x.approved?'Withdraw approval':'Approve for learners'}</button><button class="primary" data-use="${x.id}">Use this tool</button></div></article>`).join(''):'<div class="blank"><h2>Your library is ready for its first lesson</h2><p>Add a company transcript or approved reference. Attach an MP4 or WebM to make it a video lesson.</p></div>';
 document.querySelectorAll('[data-approval]').forEach(x=>x.onclick=async()=>{try{await api('review',{kind:'lesson',id:x.dataset.approval,approved:x.dataset.value==='true'});await refresh();toast('Lesson approval updated.');}catch(e){toast(e.message);}});document.querySelectorAll('[data-use]').forEach(x=>x.onclick=()=>{$('tool').value=workspace.lessons.find(l=>l.id===x.dataset.use).tool;go('coach');$('question').focus();});}
function renderReview(){$('review-list').innerHTML=workspace.drafts.length?workspace.drafts.slice().reverse().map(x=>`<article class="panel review-card"><span class="tag">${x.status==='reviewed'?'REVIEWED DRAFT':x.sourceId?'SOURCED DRAFT':'EXPERT CONTENT NEEDED'}</span><h2 style="margin-top:16px">${esc(x.question)}</h2><p>${esc(x.tool)}</p>${x.sourceId?`<p class="source-ref">Source: ${esc(x.sourceTitle)}. Check narration and visuals against the original reference.</p><label for="draft-${x.id}">Editable script and storyboard</label><textarea class="draft-editor" id="draft-${x.id}">${esc(x.script)}</textarea><div class="lesson-actions"><button class="primary" data-save-draft="${x.id}">Save edits</button><button class="secondary" data-reviewed="${x.id}">Mark reviewed</button><button class="secondary" data-export="${x.id}">Download script</button><a class="secondary" target="_blank" rel="noopener" href="https://labs.google/fx/tools/flow">Open Google Flow</a></div><p class="small">Review status does not publish a lesson. Add the final reviewed material through the lesson library.</p>`:'<p>No applicable approved procedure was found. Add the relevant expert reference or record a demonstration, then retry the request.</p><button class="primary" data-add-for="'+x.id+'">Add missing lesson</button>'}</article>`).join(''):'<div class="blank"><h2>No training gaps yet</h2><p>Requests without an applicable video appear here, with their supporting source when available.</p></div>';
 document.querySelectorAll('[data-save-draft],[data-reviewed]').forEach(x=>x.onclick=async()=>{const id=x.dataset.saveDraft||x.dataset.reviewed;try{await api('review',{id,status:x.dataset.reviewed?'reviewed':'needs-review',script:$('draft-'+id).value});await refresh();toast('Draft saved.');}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-export]').forEach(x=>x.onclick=()=>{const id=x.dataset.export;const blob=new Blob([$('draft-'+id).value],{type:'text/plain'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='toolcoach-reviewed-script.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});document.querySelectorAll('[data-add-for]').forEach(x=>x.onclick=()=>{const d=workspace.drafts.find(y=>y.id===x.dataset.addFor);$('lesson-tool').value=d.tool;$('lesson-title').value=d.question;$('lesson-dialog').showModal();});}
$('add-lesson').onclick=()=>$('lesson-dialog').showModal();$('close-dialog').onclick=()=>$('lesson-dialog').close();
$('lesson-form').onsubmit=async e=>{e.preventDefault();const file=$('lesson-video').files[0];if(file&&(file.size>25*1024*1024||!['video/mp4','video/webm'].includes(file.type))){toast('Use an MP4 or WebM under 25 MB.');return;}$('save-lesson').disabled=true;try{await api('lesson',{title:$('lesson-title').value,tool:$('lesson-tool').value,topic:$('lesson-topic').value,content:$('lesson-content').value,approved:$('lesson-approved').checked,start:$('lesson-start').value,video:file?await fileData(file):''});$('lesson-form').reset();$('lesson-dialog').close();await refresh();toast('Lesson added to your local library.');}catch(e){toast(e.message);}finally{$('save-lesson').disabled=false;}};
$('settings-form').onsubmit=async e=>{e.preventDefault();if(!$('api-key').value){toast('Paste an API key first.');return;}try{await api('connect',{key:$('api-key').value,model:$('model-name').value});$('api-key').value='';await refresh();toast('Key configured. The next lesson request will test Google access.');}catch(e){toast(e.message);}};$('disconnect').onclick=async()=>{try{await api('connect',{key:''});await refresh();toast('Local search enabled.');}catch(e){toast(e.message);}};
document.querySelectorAll('[data-answer]').forEach(x=>x.onclick=()=>{answer=x.dataset.answer;document.querySelectorAll('[data-answer]').forEach(y=>y.classList.toggle('selected',y===x));});$('check-answer').onclick=async()=>{if(!answer){toast('Choose an answer first.');return;}const correct=answer==='Tee';$('quiz-result').textContent=correct?'Correct. A tee has three openings, allowing a branch from the main run. Now find it in the 3D layout.':'Try again. Look for a fitting with three openings: two continue the run and one forms a branch.';try{await api('attempt',{correct,answer});await refresh();}catch(e){toast(e.message);}};
if(document.modelContext?.registerTool){for(const tool of [{name:'read_training_workspace',description:'Read local lesson titles, approvals and training gaps.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>{await refresh();return {lessons:workspace.lessons.map(x=>({id:x.id,title:x.title,tool:x.tool,approved:x.approved})),pending:workspace.drafts.filter(x=>x.status!=='reviewed').length};}},{name:'start_training_request',description:'Stage a tool model and learning question in the visible form without submitting to AI.',inputSchema:{type:'object',properties:{tool:{type:'string'},question:{type:'string'}},required:['tool','question'],additionalProperties:false},execute:input=>{if(typeof input.tool!=='string'||typeof input.question!=='string'||!input.tool.trim()||!input.question.trim())throw Error('Tool and question are required.');$('tool').value=input.tool.slice(0,200);$('question').value=input.question.slice(0,3000);go('coach');return {staged:true};}}])Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}
refresh().catch(e=>toast(e.message));
